"""
Static configuration for the Línea 1 plant-view Streamlit app.

Reproduces the Grafana "Producción - Línea 1" canvas panel
(grafana/dashboard_linea1.json) as a Streamlit page: the same 3D plant
layout image with live production/scrap values overlaid near each machine
group, built from the same LINE1_*_SHIFT derived rollup timeseries
hourly_production_report already writes -- no new backend needed.

Positions below are approximate (eyeballed against the image, not a
pixel-exact port of Grafana's own canvas coordinates -- that canvas's
declared coordinate space, 1200x688, doesn't match this image's native
resolution 1684x966, and a couple of its element positions actually sit
outside its own declared bounds). Tune ELEMENTS' x/y if a label ends up in
an awkward spot once you see it rendered.
"""
from datetime import date, datetime, timedelta, timezone

LOCAL_TZ = timezone(timedelta(hours=-4))

LOGO_B64 = """"""  # Empresas Polar logo, embedded as base64

# Plant layout diagram (Línea 1) -- same image used in the Grafana canvas panel,
# re-encoded as JPEG (was a 1.57MB PNG with no real transparency) and embedded as
# base64, same reasoning as the logo: Fusion's Streamlit editor has no binary-asset upload.
PLANT_IMAGE_B64 = """"""

# x/y are FRACTIONS of the plant image's width/height (0,0 = top-left,
# matching normal image coordinates -- main.py flips y for Plotly's
# paper-space, where 0 is the bottom).
ELEMENTS = [
    {"label": "Producción", "kind": "production", "target": "LINE1_MINSTER_PRODUCTION_SHIFT", "x": 0.19, "y": 0.955},
    {"label": "Producción", "kind": "production", "target": "LINE1_DI_PRODUCTION_SHIFT", "x": 0.60, "y": 0.915},
    {"label": "Merma", "kind": "scrap", "target": "LINE1_DI_SCRAP_SHIFT", "x": 0.60, "y": 0.99},
    {"label": "Producción", "kind": "production", "target": "LINE1_PRINTER_PRODUCTION_SHIFT", "x": 0.849, "y": 0.335},
    {"label": "Merma", "kind": "scrap", "target": "LINE1_PRINTER_SCRAP_SHIFT", "x": 0.849, "y": 0.415},
    {"label": "Producción", "kind": "production", "target": "LINE1_ISPRAY_PRODUCTION_SHIFT", "x": 0.215, "y": 0.0983},
]

# Fixed pixel size for every overlay box (same for Producción/Merma, per
# explicit request -- also removes any font-metric-dependent auto-sizing
# variance between environments, which is why earlier positions that looked
# clear in a local static render still overlapped once deployed to Fusion's
# actual browser rendering).
ELEMENT_WIDTH = 115
ELEMENT_HEIGHT = 46

# Matches the Grafana canvas panel exactly (grafana/dashboard_linea1.json):
# production elements use super-light-blue/dark-blue, scrap elements use
# super-light-red/dark-red.
ELEMENT_COLORS = {
    "production": {"bg": "#dbeafe", "border": "#1e40af"},
    "scrap": {"bg": "#fee2e2", "border": "#991b1b"},
}

CUSTOM_CSS = """
    <style>
    .block-container {
        padding-top: 3rem !important;
        padding-bottom: 1rem !important;
    }
    .custom-title {
        margin-top: 10px !important;
        margin-bottom: 5px !important;
        font-weight: 700;
        color: #1e293b;
        font-size: 1.9rem;
    }
    </style>
"""


def current_shift_label(now_local: datetime = None) -> str:
    """"Turno actual" label for display -- day shift 06:00-18:00 local,
    night shift 18:00-06:00, matching the shift convention used everywhere
    else in this project."""
    now_local = now_local or datetime.now(LOCAL_TZ)
    if 6 <= now_local.hour < 18:
        return "1er turno (día)"
    return "2do turno (noche)"
